from taf.gnb.oam.coam.cu.utilities.http_client import HttpClient


class PMv1HttpClient(HttpClient):
    """
    IMPORTANT: This component has been removed, PMv2 should be used starting from 26R1
    This class provides a client for the PM V1 API.
    """
    def __init__(self, base_url, connection_alias):
        super(PMv1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/pm/v1"

    def get_counter(self, measurement_id, dimension_dist_name, counter_id, timeout=30, **kwargs):
        endpoint = f'/measurements/{measurement_id}/counters/{counter_id}'
        headers = {
            "Content-Type": "application/json",
        }
        data = {
            "dimensionDistributionName": dimension_dist_name,
            "startTimeLowerLimit": kwargs.get('start_time_lower_limit'),
            "startTimeUpperLimit": kwargs.get('start_time_upper_limit')
        }

        return self._send_get_request(endpoint=endpoint, payload=data, timeout=timeout, headers=headers)

    def get_measurement_info(self, measurement_id):
        endpoint = f"/measurements/{measurement_id}/info"
        headers = {
            "accept": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers)

    def get_counter_info(self, counter_id, measurement_id):
        endpoint = f"/measurements/{measurement_id}/counters/{counter_id}/info"
        headers = {
            "accept": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers)
